use super::*;

/// The frontend FieldType string for a `bsc_data::FieldType`.
#[cfg(feature = "source-stage")]
pub(crate) fn field_type_str(t: FieldType) -> &'static str {
    match t {
        FieldType::String => "string",
        FieldType::Number => "number",
        FieldType::Bool => "bool",
        FieldType::Date => "date",
        FieldType::Money => "money",
        FieldType::Enum => "enum",
        FieldType::Ref => "ref",
    }
}
